import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';const{db,send,asset,reviewed}=await import('./reply-runtime-20261015.mjs');const dir='artifacts/local-reassurance-20261019';const rows=JSON.parse(await fs.readFile(dir+'/preflight.json'));
const bodies={
'STEPHEN T MILIC':"We operate in Windsor and also serve Toronto and the wider GTA, Stephen, including moves within the GTA. We cover Southwestern Ontario too. You can contact me here to coordinate your clients' moves, and we'll confirm the details and provide a clear estimate upfront. Happy to be another moving option for your clients. - John",
'Elle Cee Staging Inc':"Thanks, that helps—a truck, two movers, blankets and stretch wrap. Just to confirm the $120 rate you mentioned is per hour: is there a minimum booking, and is travel included? We'd like to get the arrangement clear so it works smoothly for your staging and unstaging jobs. - John",
'Sabrina Italiano':"Thanks for adding us to your roster, Sabrina! Yes, you can note piano moves, packing/unpacking, furniture disassembly/reassembly, staging and unstaging, and labour-only help. We confirm the scope and access for each job before quoting. - John",
'Carlo Malatesta':"Here you go, Carlo—our Newmarket card to save and share with your clients. You can call or text me here whenever someone needs moving help. Thanks for keeping us in mind! - John",
'NAVNEET CHAWLA':"Here you go, Navneet—our Brampton card to save and share when a client needs moving help. You can call or text me here. - John"};
const plans=[];for(const r of rows){const c=r.contact;if(!bodies[c.name])continue;plans.push({id:c.id,name:c.name,phone:c.phone,city:c.city,latest:r.thread.at(-1).id,from:'+14374650584',body:bodies[c.name],media_urls:['Carlo Malatesta','NAVNEET CHAWLA'].includes(c.name)?[await asset(c.city)]:[],followup_key:'20261019-local-reassurance',note:'Contextual owner-authorized reply. Confirmed service coverage, requested card or stager scope clarification; no invented office, crew availability or rate inclusions.'});}
await fs.writeFile(dir+'/send-plan.json',JSON.stringify(plans,null,2));const results=[];for(const p of plans){try{const r=await send(p);results.push({name:p.name,state:r.state});}catch(e){results.push({name:p.name,state:'held',reason:e.message});}await fs.writeFile(dir+'/send-results.json',JSON.stringify(results,null,2));}
const recent=JSON.parse(await fs.readFile(dir+'/review.json')).rows;for(const r of recent.filter(r=>['JASON COHEN','Melanie Cheung','KATERINA HRYB','KAYODE ADEKOYA','Kunwar Singh'].includes(r.contact.name))){const last=r.thread.at(-1);const [now]=await db('market_touches',{contact_id:'eq.'+r.contact.id,order:'created_at.desc,id.desc',limit:'1'});if(now.id===last.id)await reviewed(last.id,'Positive reaction or thank-you; no additional message needed.');}
console.log(JSON.stringify(results));
